def wolfeKernelRegion (N : JLMS.AtomicDualModel 𝕜 L)
    (S : JLMS.CZero 𝕜 L →L[𝕜] JLMS.CZero 𝕜 K) (V : Set L) (δ : ℝ) : Set K :=
  {y | δ < wolfeMass N (weakStarAdjoint S (wolfeDirac y)) V}

